INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64616209', 64616209, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pekerjaan Sewa Layanan Disaster Recovery Center (DRC) TA. 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 98400000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PKT', '1) Mendapatkan layanan atas fasilitas Data Center milik PDSI BP Batam sebagai Pusat Pemulihan Data; 2) Mendapatkan jaminan keamanan akses pada jaringan dan fasilitas di Pusat Pemulihan Data atau Pusat Data; 3) Mendapatkan jaminan kerahasiaan atas seluruh informasi terkait perangkat milik Bappenas; 4) Mendapatkan jaminan sesuai Service Level Agreement yang berlaku di PDSI BP Batam; 5) Mendapatkan akses melakukan pengawasan dan memeriksa pekerjaan terkait yang dilaksanakan oleh PDSI BP Batam; 6) Menyediakan laporan-laporan secara periodik mengenai pelaksanaan pekerjaan terkait yang dilaksanakan oleh PDSI BP Batam; 7) Memberikan fasilitas berupa sarana dan prasarana yang disediakan oleh Pihak Kedua untuk kelancaran pelaksanaan pekerjaan sesuai ketentuan; a. Menyediakan alat transportasi vertikal berupa lift menuju ke ruangan Pusat Pemulihan Data yang dapat digunakan untuk mengangkut orang dan peralatan teknologi informasi sesuai standar yang layak; b. PDSI BP Batam Bertanggung jawab terhadap beban kerugian, apabila terjadi kecelakaan pengangkutan peralatan Pusat Data akibat lift yang tidak sesuai; c. PDSI BP Batam Menjaga keamanan gedung dari pencurian, gangguan keamanan, kebakaran dan lainnya terhadap peralatan Data Center miliknya sebagai Pusat Pemulihan Data/Disaster Recovery Centre; d. PDSI BP Batam Memberi kemudahan aksesibilitas ke dalam gedung/ruang Disaster Recovery Centre/Data Center bagi petugas pengelola dari Pihak Bappenas sesuai dengan standar operasional dan prosedur yang berlaku; e. PDSI BP Batam Menyediakan fasilitas catu daya listrik utama yang bersumber dari PLN, catu daya listrik pendukung yang terdiri dari genset dan UPS untuk operasional server di Data Center milik Pihak Kedua dengan sumber listrik sebesar maksimal 2.8 KVA per server rack dan fire suppression; f. PDSI BP Batam Menyediakan fasilitas AC yang beroperasi selama 7x24 jam dengan suhu ruangan dijaga pada batas antara 18o sampai dengan 27o Celcius dan kelembaban udara antara 40% sampai dengan 60%; g. PDSI BP Batam Memfasilitasi Bappenas dalam hal keamanan dengan menugaskan security atau petugas keamanan selama 24 jam serta adanya Security Gate dan Radio Frequency Identification (RFID) Gate; h. PDSI BP Batam Menyediakan perangkat pengawasan berupa CCTV pada ruang Data Center; i. PDSI BP Batam Bersedia menyediakan fasilitas dan sarana penunjang di Data Center berupa ruang tenant untuk dimanfaatkan oleh Bappenas; j. PDSI BP Batam Melaksanakan dan menyelesaikan pekerjaan secara cermat, akurat dan penuh tanggung jawab dengan menyediakan tenaga kerja, bahan-bahan, peralatan, angkutan ke atau dari lapangan, dan segala pekerjaan permanen maupun sementara yang diperlukan untuk pelaksanaan, penyelesaian dan perbaikan pekerjaan yang dirinci dalam Kontrak; k. PDSI BP Batam Mengambil langkah-langkah yang cukup memadai untuk melindungi lingkungan tempat kerja dan membatasi perusakan dan gangguan kepada masyarakat maupun miliknya akibat kegiatan Pihak Kedua.', 'Pekerjaan Sewa Layanan Disaster Recovery Center (DRC) TA. 2026', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1650343);
