INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64578277', 64578277, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'PAS23 RUTAN KELAS II B MALINO', 'Pengadaan Pemeliharaan Scanner untuk kegiatan pemeliharaan peralatan dan mesin pada Rumah Tahanan Negara Kelas IIB Malino-Sulawesi Selatan Tahun Anggaran 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Gowa (Kab.)', 1800000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, Unit, @ 1800000 )', 'Pekerjaan ini meliputi kegiatan pemeliharaan dan perbaikan ringan terhadap perangkat scanner yang digunakan dalam mendukung kegiatan administrasi, kearsipan, dan pelayanan perkantoran di Rumah Tahanan Negara Kelas IIB Malino. Pemeliharaan dilakukan untuk memastikan scanner berfungsi dengan baik, optimal, dan siap digunakan secara berkelanjutan.', 'Kegiatan pemeliharaan scanner meliputi, namun tidak terbatas pada: Pemeriksaan Awal Perangkat Pemeriksaan kondisi fisik scanner; Pemeriksaan fungsi tombol, sensor, dan mekanisme pemindai; Pemeriksaan koneksi kabel dan antarmuka perangkat. Pembersihan dan Perawatan Pembersihan kaca pemindai, roller, dan bagian dalam scanner; Pembersihan debu dan kotoran yang dapat mengganggu hasil pemindaian; Pelumasan ringan pada bagian mekanis tertentu (jika diperlukan). Pengujian Fungsi dan Kualitas Scan Pengujian hasil pemindaian (ketajaman, warna, dan kejelasan); Pengujian kecepatan dan stabilitas proses scan; Penyesuaian (setting) resolusi dan software pendukung. Perbaikan Ringan dan Penggantian Komponen Minor Penggantian komponen kecil yang aus atau rusak (roller, belt, atau kabel); Perbaikan gangguan fungsi ringan yang tidak memerlukan penggantian unit utama; Penyesuaian ulang agar scanner dapat beroperasi normal. Pembaruan Perangkat Lunak (jika diperlukan) Instalasi atau pembaruan driver scanner; Penyesuaian kompatibilitas dengan sistem komputer yang digunakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1651556);
