INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64636992', 64636992, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS TENAGA KERJA, TRANSMIGRASI, DAN ENERGI', 'Perencanaan Pembangunan PLTS di Wilayah DKI Jakarta', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 678272000, 'July 2026', 'APBD', 1, 1, '1', 'melaksanakan jasa konsultansi perencanaan pembangunan PLTS Atap on grid sebagai acuan dalam pelaksanaan pembangunan PLTS atap on grid pada gedung dan sarana milik pemerintah provinsi DKI Jakarta', 'ruang lingkup pekerjaan pembuatan dokumen perencanaan pembangunan PLTS atap on grid di gedung dan sarana milik pemerintah Provinsi DKI Jakarta adalah sebagi berikut: 1. persiapan meliputi persiapan dan koordinasi dengan instansi terkait, inventarisasi data gedung, penyusunan jadwal, kuesioner dan mapping area gedung yang akan disurvei 2. pelaksanaan meliputi : a. pelaksanaan survei dan pengambilan data teknis dan non teknis gedung yang diperlukan, b. penyusunan laporan hasil survei, c. evaluasi kelayakan teknis dan non teknis terhadap hasil survei, d. penyusunan spesifikasi tenknis sistem PLTS yang meliputi gambar diagram kelistrikan, layout atap, perhitungan kebutuhan dan jenis komponen sistem yang diperlukan seperti modul surya, DC combiner, Inverter, Data Logger, Panel AC, sistem proteksi dan lainnya, e. melakukan analisis perhitungan produksi listrik dan potensi penghematan biaya tagihan listrik dari sistem PLTS yang direncanakan di setiap gedung, f. penyusunan DED dan RAB sistem PLTS yang direncanakan, g. penyusunan rencana kerja dan syarat-syarat administrasi, h. penyusunan dokumen teknis perencanaan pembangunan PLTS atap on grid di gedung dan sarana milik pemerintah Provinsi DKI Jakarta 3. pelaporan meliputi : a. laporan pendahuluan, b. laporan antara, c. laporan draft akhir, d. laporan akhir', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1651796);
