INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64578496', 64578496, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'PAS23 RUTAN KELAS II B MALINO', 'Pengadaan  Extra Voeding bagi WBP selama Bulan Puasa pada Rumah Tahanan Negara Kelas IIB Malino-Sulawesi Selatan Tahun Anggaran 2026', 'Barang', 'E-Purchasing', 'Sulawesi Selatan, Gowa (Kab.)', 20250000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 4050, OH, @ 5000 )', 'Pekerjaan ini meliputi pengadaan, penyediaan, dan penyaluran makanan tambahan (extra voeding) bagi Warga Binaan Pemasyarakatan (WBP) yang menjalankan ibadah puasa di Rumah Tahanan Negara Kelas IIB Malino. Extra voeding diberikan sebagai tambahan asupan gizi untuk menjaga kesehatan, kebugaran, dan daya tahan tubuh WBP selama menjalankan ibadah puasa.', 'Extra voeding yang disediakan harus memenuhi ketentuan sebagai berikut: Jenis Extra Voeding Makanan tambahan berupa kudapan atau makanan siap konsumsi; Dapat berupa makanan basah atau kering yang sesuai dikonsumsi saat berbuka atau sahur; Mudah dikonsumsi, bergizi, dan tidak cepat basi. Kandungan Gizi Mengandung karbohidrat, protein, dan lemak dalam komposisi seimbang; Memiliki nilai gizi yang mendukung kebutuhan energi tambahan WBP selama puasa; Menggunakan bahan pangan yang aman dan layak konsumsi. Keamanan dan Kualitas Bahan makanan segar dan berkualitas baik; Tidak mengandung bahan berbahaya atau zat aditif yang dilarang; Diolah secara higienis sesuai standar keamanan pangan; Memiliki izin edar atau berasal dari penyedia yang memiliki izin usaha pangan. Penyajian dan Pengemasan Dikemas secara bersih, aman, dan higienis; Kemasan mampu menjaga mutu makanan hingga waktu konsumsi; Mudah didistribusikan dan disajikan kepada WBP', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1652709);
