INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64578497', 64578497, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'PAS23 RUTAN KELAS II B MALINO', 'Pengadaan Barang untuk Kegiatan Pemulasaran Bagi WBP pada Rumah Tahanan Negara Kelas IIB Malino-Sulawesi Selatan Tahun Anggaran 2026', 'Barang', 'Pengadaan Langsung', 'Sulawesi Selatan, Gowa (Kab.)', 1000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, Orang, @ 1000000 )', 'Pekerjaan ini meliputi pengadaan barang-barang kebutuhan pemulasaran bagi Warga Binaan Pemasyarakatan (WBP) yang meninggal dunia di lingkungan Rumah Tahanan Negara Kelas IIB Malino. Pengadaan dilakukan untuk mendukung pelaksanaan pemulasaran secara layak, bermartabat, manusiawi, serta sesuai dengan ketentuan agama, budaya, dan peraturan perundang-undangan yang berlaku.', 'Barang pemulasaran yang disediakan harus memenuhi ketentuan sebagai berikut: Kain Kafan Berbahan kain katun/putih polos; Bersih, tidak tembus pandang berlebihan, dan tidak mudah robek; Ukuran mencukupi untuk jenazah dewasa/anak sesuai kebutuhan; Kondisi baru dan layak pakai. Perlengkapan Pemandian Jenazah Sabun mandi dan bahan pembersih yang aman; Sarung tangan sekali pakai; Ember/baskom dan perlengkapan pendukung lainnya; Kondisi baru, bersih, dan higienis. Perlengkapan Pengemasan Jenazah Kantong jenazah atau perlengkapan pembungkus sesuai standar; Tali pengikat kain kafan; Penutup jenazah yang layak dan sopan; Kondisi baru dan tidak cacat. Perlengkapan Penunjang Pemulasaran Alas atau tandu jenazah (bila diperlukan); Perlengkapan kebersihan dan desinfeksi area; Peralatan pendukung lain yang relevan dengan proses pemulasaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1655644);
